-- Hand edit: audit logs are append-only. Deletes stay possible for retention jobs and
-- environment deletion.
CREATE OR REPLACE FUNCTION "openverify_reject_audit_log_update"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'audit_logs is append-only';
END;
$$;--> statement-breakpoint
CREATE TRIGGER "audit_logs_reject_update" BEFORE UPDATE ON "audit_logs" FOR EACH ROW EXECUTE FUNCTION "openverify_reject_audit_log_update"();
